    expect(proof.empty.ink).toBe(0);
    expect(proof.cleared).toBe(true);
    await page.getByLabel('Fixture').selectOption('hotkey-input');
    await expect(stage).not.toHaveAttribute('data-viewer-tank-artwork');
    expect(errors).toEqual([]);
  });
}

